        "ChangedAtSource" = CASE WHEN "ChangedAtSource" = 'field-manager' THEN 'last-write-before-delete' ELSE "ChangedAtSource" END
    WHERE "Verb" = 'delete' AND ("CurrentObject" IS NOT NULL OR "ChangedAtSource" = 'field-manager');
